112	        => StoreStoredProcedure is null
113	            && _entries.Count > 0
114	            && GetTableMapping(_entries[0].EntityType) is { IsSplitFragmentOptional: true } tableMapping
115	            && tableMapping.ColumnMappings
116	                .Where(m => !m.Property.IsPrimaryKey())
117	                .All(m => _entries[0].GetOriginalValue(m.Property) is null);
