124	        => StoreStoredProcedure is null
125	            && _entries.Count > 0
126	            && GetTableMapping(_entries[0].EntityType) is { IsSplitFragmentOptional: true } tableMapping
127	            && tableMapping.ColumnMappings
128	                .Where(m => !m.Property.IsPrimaryKey())
129	                .All(m => _entries[0].GetCurrentValue(m.Property) is null);
