154	    /// <inheritdoc />
155	    public virtual void AddEntry(IUpdateEntry entry, bool mainEntry)
156	    {
157	        AssertColumnsNotInitialized();
158	
159	        switch (entry.EntityState)
160	        {
161	            case EntityState.Deleted:
162	            case EntityState.Modified:
163	            case EntityState.Added:
164	                break;
165	            default:
166	                if (_sensitiveLoggingEnabled)
167	                {
168	                    throw new InvalidOperationException(
169	                        RelationalStrings.ModificationCommandInvalidEntityStateSensitive(
170	                            entry.EntityType.DisplayName(),
171	                            entry.BuildCurrentValuesString(entry.EntityType.FindPrimaryKey()!.Properties),
172	                            entry.EntityState));
173	                }
174	
175	                throw new InvalidOperationException(
176	                    RelationalStrings.ModificationCommandInvalidEntityState(
177	                        entry.EntityType.DisplayName(),
178	                        entry.EntityState));
179	        }
180	
181	        if (mainEntry)
182	        {
183	            Check.DebugAssert(!_mainEntryAdded, "Only expected a single main entry");
184	
185	            for (var i = 0; i < _entries.Count; i++)
186	            {
187	                ValidateState(entry, _entries[i]);
188	            }
189	
190	            _mainEntryAdded = true;
191	            _entries.Insert(0, entry);
192	
193	            _entityState = entry.SharedIdentityEntry == null
194	                ? entry.EntityState
195	                : entry.SharedIdentityEntry.EntityType == entry.EntityType
196	                || entry.SharedIdentityEntry.EntityType.GetTableMappings()
197	                    .Any(m => m.Table.Name == TableName && m.Table.Schema == Schema)
198	                    ? EntityState.Modified
199	                    : entry.EntityState;
200	
201	            // An optional entity-splitting fragment's row may not exist yet. If every non-key value mapped to it was
202	            // null when the entity was loaded, assume the row is absent and insert it rather than updating it.
203	            if (_entityState == EntityState.Modified
204	                && IsOptionalSplitFragmentRowAssumedAbsent)
205	            {
206	                _entityState = EntityState.Added;
207	            }
208	            // Conversely, if the row exists but every non-key value mapped to it is now null, delete it rather than
209	            // leaving behind an all-null row that a later save would misdetect as absent and try to re-insert.
210	            else if (_entityState == EntityState.Modified
211	                && IsOptionalSplitFragmentPayloadAllNull)
212	            {
213	                _entityState = EntityState.Deleted;
214	            }
215	        }
216	        else
217	        {
218	            if (_mainEntryAdded)
219	            {
220	                ValidateState(_entries[0], entry);
221	            }
222	
223	            _entries.Add(entry);
224	        }
225	    }
