227	    private void ValidateState(IUpdateEntry mainEntry, IUpdateEntry entry)
228	    {
229	        var mainEntryState = mainEntry.SharedIdentityEntry == null
230	            ? mainEntry.EntityState
231	            : EntityState.Modified;
232	        if (mainEntryState == EntityState.Modified)
233	        {
234	            return;
235	        }
236	
237	        var entryState = entry.SharedIdentityEntry == null
238	            ? entry.EntityState
239	            : EntityState.Modified;
240	        if (mainEntryState != entryState)
241	        {
242	            if (_sensitiveLoggingEnabled)
243	            {
244	                throw new InvalidOperationException(
245	                    RelationalStrings.ConflictingRowUpdateTypesSensitive(
246	                        entry.EntityType.DisplayName(),
247	                        entry.BuildCurrentValuesString(entry.EntityType.FindPrimaryKey()!.Properties),
248	                        entryState,
249	                        mainEntry.EntityType.DisplayName(),
250	                        mainEntry.BuildCurrentValuesString(mainEntry.EntityType.FindPrimaryKey()!.Properties),
251	                        mainEntryState));
252	            }
253	
254	            throw new InvalidOperationException(
255	                RelationalStrings.ConflictingRowUpdateTypes(
256	                    entry.EntityType.DisplayName(),
257	                    entryState,
258	                    mainEntry.EntityType.DisplayName(),
259	                    mainEntryState));
260	        }
261	    }
