294	    private List<IColumnModification> GenerateColumnModifications()
295	    {
296	        var state = EntityState;
297	        var adding = state == EntityState.Added;
298	        var updating = state == EntityState.Modified;
299	        var deleting = state == EntityState.Deleted;
300	        var columnModifications = new List<IColumnModification>();
301	        Dictionary<string, ColumnValuePropagator>? sharedTableColumnMap = null;
302	
303	        // Detect table-splitting and populate shared columns to propagate values back to the sharing entries.
304	        if (_entries.Count > 1
305	            || (_entries is [var singleEntry]
306	                && (singleEntry.SharedIdentityEntry is not null
307	                    || singleEntry.EntityType.GetComplexProperties()
308	                        .Any(cp => !cp.IsCollection && !cp.ComplexType.IsMappedToJson()))))
309	        {
310	            Check.DebugAssert(StoreStoredProcedure is null, "Multiple entries/shared identity not supported with stored procedures");
311	
312	            sharedTableColumnMap = [];
313	
314	            if (_comparer != null
315	                && _entries.Count > 1)
316	            {
317	                _entries.Sort(_comparer);
318	            }
319	
320	            foreach (var entry in _entries)
321	            {
322	                var tableMapping = GetTableMapping(entry.EntityType);
323	                if (tableMapping == null)
324	                {
325	                    continue;
326	                }
327	
328	                if (entry.SharedIdentityEntry != null)
329	                {
330	                    var sharedTableMapping = entry.EntityType != entry.SharedIdentityEntry.EntityType
331	                        ? GetTableMapping(entry.SharedIdentityEntry.EntityType)
332	                        : tableMapping;
333	                    if (sharedTableMapping != null)
334	                    {
335	                        HandleSharedColumns(
336	                            entry.SharedIdentityEntry.EntityType, entry.SharedIdentityEntry, sharedTableMapping, deleting,
337	                            sharedTableColumnMap);
338	                    }
339	                }
340	
341	                HandleSharedColumns(entry.EntityType, entry, tableMapping, deleting, sharedTableColumnMap);
342	            }
343	        }
344	
345	        // A replaced dependent's JSON has to be cleared even if no current entry has JSON
346	        if (!deleting
347	            && _entries.Any(e => HasJson(e.EntityType)
348	                || e.SharedIdentityEntry is { EntityState: EntityState.Deleted } replacedEntry && HasJson(replacedEntry.EntityType)))
349	        {
350	            HandleJson(columnModifications);
351	        }
352	
353	        foreach (var entry in _entries)
354	        {
355	            if (entry.EntityType.IsMappedToJson())
356	            {
357	                continue;
358	            }
359	
360	            var nonMainEntry = !_mainEntryAdded || entry != _entries[0];
361	
362	            var optionalDependentWithAllNull = false;
363	            if (StoreStoredProcedure is null)
364	            {
365	                var tableMapping = GetTableMapping(entry.EntityType);
366	                if (tableMapping is null)
367	                {
368	                    continue;
369	                }
370	
371	                optionalDependentWithAllNull =
372	                    entry.EntityState is EntityState.Modified or EntityState.Added
373	                    && tableMapping.Table.IsOptional(entry.EntityType)
374	                    && tableMapping.Table.GetRowInternalForeignKeys(entry.EntityType).Any()
375	                    && entry.EntityType.GetComplexProperties()
376	                        .All(p => !p.ComplexType.IsMappedToJson() || entry.GetCurrentValue(p) == null);
377	
378	                HandleNonJson(entry, entry.EntityType, tableMapping, nonMainEntry, ref optionalDependentWithAllNull);
379	            }
380	            else
381	            {
382	                HandleSprocs(entry, nonMainEntry, ref optionalDependentWithAllNull);
383	            }
384	
385	            if (optionalDependentWithAllNull && _logger != null)
386	            {
387	                if (_sensitiveLoggingEnabled)
388	                {
389	                    _logger.OptionalDependentWithAllNullPropertiesWarningSensitive(entry);
390	                }
391	                else
392	                {
393	                    _logger.OptionalDependentWithAllNullPropertiesWarning(entry);
394	                }
395	            }
396	        }
397	
398	        return columnModifications;
399	
400	        static bool HasJson(IEntityType entityType)
401	            => entityType.IsMappedToJson()
402	                || entityType.GetFlattenedComplexProperties().Any(cp => cp.ComplexType.IsMappedToJson())
403	                || entityType.GetNavigations().Any(e => e.IsCollection && e.TargetEntityType.IsMappedToJson());
404	
405	        void HandleNonJson(
406	            IUpdateEntry entry,
407	            ITypeBase structuralType,
408	            ITableMapping tableMapping,
409	            bool nonMainEntry,
410	            ref bool optionalDependentWithAllNull)
411	        {
412	            foreach (var columnMapping in tableMapping.ColumnMappings)
413	            {
414	                HandleColumn(entry, columnMapping, nonMainEntry, ref optionalDependentWithAllNull);
415	            }
416	
417	            foreach (var complexProperty in structuralType.GetComplexProperties())
418	            {
419	                var complexTableMapping = GetTableMapping(complexProperty.ComplexType);
420	                if (complexTableMapping != null)
421	                {
422	                    HandleNonJson(entry, complexProperty.ComplexType, complexTableMapping, nonMainEntry, ref optionalDependentWithAllNull);
423	                }
424	            }
425	        }
426	
427	        void HandleColumn(
428	            IUpdateEntry entry,
429	            IColumnMappingBase columnMapping,
430	            bool nonMainEntry,
431	            ref bool optionalDependentWithAllNull)
432	        {
433	            var property = columnMapping.Property;
434	            var column = columnMapping.Column;
435	            var storedProcedureParameter = columnMapping is IStoredProcedureParameterMapping parameterMapping
436	                ? parameterMapping.Parameter
437	                : null;
438	            var isKey = property.IsPrimaryKey();
439	            var isCondition = !adding
440	                && (isKey
441	                    || storedProcedureParameter is { ForOriginalValue: true }
442	                    || (property.IsConcurrencyToken && storedProcedureParameter is null));
443	
444	            // Store-generated properties generally need to be read back (unless we're deleting).
445	            // One exception is if the property is mapped to a non-output parameter.
446	            var readValue = state != EntityState.Deleted
447	                && ColumnModification.IsStoreGenerated(entry, property)
448	                && (storedProcedureParameter is null || storedProcedureParameter.Direction.HasFlag(ParameterDirection.Output));
449	
450	            ColumnValuePropagator? columnPropagator = null;
451	            sharedTableColumnMap?.TryGetValue(column.Name, out columnPropagator);
452	
453	            var writeValue = false;
454	            if (!readValue)
455	            {
456	                if (adding)
457	                {
458	                    writeValue = property.GetBeforeSaveBehavior() == PropertySaveBehavior.Save
459	                        || entry.HasStoreGeneratedValue(property);
460	
461	                    columnPropagator?.TryPropagate(columnMapping, entry);
462	                }
463	                else if (storedProcedureParameter is not { ForOriginalValue: true }
464	                         && !deleting
465	                         && ((updating && property.GetAfterSaveBehavior() == PropertySaveBehavior.Save)
466	                             || (!isKey && nonMainEntry)
467	                             || entry.SharedIdentityEntry != null))
468	                {
469	                    // Note that for stored procedures we always need to send all parameters, regardless of whether the property
470	                    // actually changed.
471	                    writeValue = !columnPropagator?.TryPropagate(columnMapping, entry)
472	                        ?? (entry.IsLoaded(property)
473	                            && (entry.EntityState == EntityState.Added
474	                                || entry.EntityState == EntityState.Deleted
475	                                || ColumnModification.IsModified(entry, property)
476	                                || StoreStoredProcedure is not null));
477	                }
478	            }
479	
480	            if (readValue
481	                || writeValue
482	                || isCondition)
483	            {
484	                var columnModificationParameters = new ColumnModificationParameters(
485	                    entry,
486	                    property,
487	                    column,
488	                    _generateParameterName!,
489	                    columnMapping.TypeMapping,
490	                    readValue,
491	                    writeValue,
492	                    isKey,
493	                    isCondition,
494	                    _sensitiveLoggingEnabled);
495	
496	                var columnModification = CreateColumnModification(columnModificationParameters);
497	
498	                if (columnPropagator != null
499	                    && column.PropertyMappings.Count != 1)
500	                {
501	                    if (columnPropagator.ColumnModification != null)
502	                    {
503	                        columnPropagator.ColumnModification.AddSharedColumnModification(columnModification);
504	
505	                        return;
506	                    }
507	
508	                    columnPropagator.ColumnModification = columnModification;
509	                }
510	
511	                columnModifications.Add(columnModification);
512	
513	                if (optionalDependentWithAllNull
514	                    && (columnModification.IsWrite
515	                        || (columnModification.IsCondition && !isKey))
516	                    && columnModification.Value is not null)
517	                {
518	                    optionalDependentWithAllNull = false;
519	                }
520	            }
521	            else if (optionalDependentWithAllNull
522	                     && state == EntityState.Modified
523	                     && property.DeclaringType == entry.EntityType
524	                     && entry.GetCurrentValue(property) is not null)
525	            {
526	                optionalDependentWithAllNull = false;
527	            }
528	        }
529	
530	        void HandleSprocs(IUpdateEntry entry, bool nonMainEntry, ref bool optionalDependentWithAllNull)
531	        {
532	            var storedProcedureMapping = GetStoredProcedureMapping(entry.EntityType, EntityState);
533	            Check.DebugAssert(storedProcedureMapping is not null, "No sproc mapping but StoredProcedure is not null");
534	            var storedProcedure = storedProcedureMapping.StoredProcedure;
535	
536	            // Stored procedures may have an additional rows affected result column or return value, which does not have a
537	            // property/column mapping but still needs to have be represented via a column modification.
538	            // Note that for rows affected parameters/result columns, we add column modifications below along with regular parameters/
539	            // result columns; for return value we do that here.
540	            if (storedProcedure.FindRowsAffectedParameter() is { } rowsAffectedParameter)
541	            {
542	                RowsAffectedColumn = rowsAffectedParameter.StoreParameter;
543	            }
544	            else if (storedProcedure.FindRowsAffectedResultColumn() is { } rowsAffectedResultColumn)
545	            {
546	                RowsAffectedColumn = rowsAffectedResultColumn.StoreResultColumn;
547	            }
548	            else if (storedProcedureMapping.StoreStoredProcedure.ReturnValue is { } rowsAffectedReturnValue)
549	            {
550	                RowsAffectedColumn = rowsAffectedReturnValue;
551	
552	                columnModifications.Add(
553	                    CreateColumnModification(
554	                        new ColumnModificationParameters(
555	                            entry: null,
556	                            property: null,
557	                            rowsAffectedReturnValue,
558	                            _generateParameterName!,
559	                            rowsAffectedReturnValue.StoreTypeMapping,
560	                            valueIsRead: true,
561	                            valueIsWrite: false,
562	                            columnIsKey: false,
563	                            columnIsCondition: false,
564	                            _sensitiveLoggingEnabled)));
565	            }
566	
567	            // In TPH, the sproc has parameters for all entity types in the hierarchy; we must generate null column modifications
568	            // for parameters for unrelated entity types.
569	            // Enumerate over the sproc parameters in order, trying to match a corresponding parameter mapping.
570	            // Note that we produce the column modifications in the same order as their sproc parameters; this is important and assumed
571	            // later in the pipeline.
572	            foreach (var parameter in StoreStoredProcedure.Parameters)
573	            {
574	                if (parameter.FindParameterMapping(entry.EntityType) is { } parameterMapping)
575	                {
576	                    HandleColumn(entry, parameterMapping, nonMainEntry, ref optionalDependentWithAllNull);
577	                    continue;
578	                }
579	
580	                // The parameter has no corresponding mapping; this is either a sibling property in a TPH hierarchy or a rows affected
581	                // output parameter. Note that we set IsRead to false since we don't propagate the output parameter.
582	                columnModifications.Add(
583	                    CreateColumnModification(
584	                        new ColumnModificationParameters(
585	                            entry: null,
586	                            property: null,
587	                            parameter,
588	                            _generateParameterName!,
589	                            parameter.StoreTypeMapping,
590	                            valueIsRead: false,
591	                            valueIsWrite: parameter.Direction.HasFlag(ParameterDirection.Input),
592	                            columnIsKey: false,
593	                            columnIsCondition: false,
594	                            _sensitiveLoggingEnabled)));
595	            }
596	
597	            foreach (var resultColumn in StoreStoredProcedure.ResultColumns)
598	            {
599	                if (resultColumn.FindColumnMapping(entry.EntityType) is { } resultColumnMapping)
600	                {
601	                    HandleColumn(entry, resultColumnMapping, nonMainEntry, ref optionalDependentWithAllNull);
602	                    continue;
603	                }
604	
605	                // The result column has no corresponding mapping; this is either a sibling property in a TPH hierarchy or a rows
606	                // affected result column. Note that we set IsRead to false since we don't propagate the result column.
607	                columnModifications.Add(
608	                    CreateColumnModification(
609	                        new ColumnModificationParameters(
610	                            entry: null,
611	                            property: null,
612	                            resultColumn,
613	                            _generateParameterName!,
614	                            resultColumn.StoreTypeMapping,
615	                            valueIsRead: false,
616	                            valueIsWrite: false,
617	                            columnIsKey: false,
618	                            columnIsCondition: false,
619	                            _sensitiveLoggingEnabled)));
620	            }
621	        }
622	
623	        void HandleSharedColumns(
624	            ITypeBase structuralType,
625	            IUpdateEntry entry,
626	            ITableMapping tableMapping,
627	            bool deleting,
628	            Dictionary<string, ColumnValuePropagator> sharedTableColumnMap)
629	        {
630	            InitializeSharedColumns(entry, tableMapping, deleting, sharedTableColumnMap);
631	
632	            foreach (var complexProperty in structuralType.GetComplexProperties())
633	            {
634	                var complexTableMapping = GetTableMapping(complexProperty.ComplexType);
635	                if (complexTableMapping != null)
636	                {
637	                    HandleSharedColumns(
638	                        complexProperty.ComplexType, entry, complexTableMapping, deleting, sharedTableColumnMap);
639	                }
640	            }
641	        }
