643	        static List<JsonPartialUpdatePathEntry>? FindJsonPartialUpdateInfo(IUpdateEntry entry, List<IUpdateEntry> processedEntries)
644	        {
645	            var result = new List<JsonPartialUpdatePathEntry>();
646	            var currentEntry = entry;
647	            var currentOwnership = currentEntry.EntityType.FindOwnership()!;
648	
649	            while (currentEntry is not null && currentEntry.EntityType.IsMappedToJson())
650	            {
651	                var jsonPropertyName = currentEntry.EntityType.GetJsonPropertyName()!;
652	                currentOwnership = currentEntry.EntityType.FindOwnership()!;
653	                var previousEntry = currentEntry;
654	#pragma warning disable EF1001 // Internal EF Core API usage.
655	                currentEntry = ((InternalEntityEntry)currentEntry).StateManager.FindPrincipal(
656	                    (InternalEntityEntry)currentEntry, currentOwnership);
657	#pragma warning restore EF1001 // Internal EF Core API usage.
658	
659	                if (currentEntry == null || processedEntries.Contains(currentEntry))
660	                {
661	                    return null;
662	                }
663	
664	                var ordinal = default(int?);
665	                if (!currentOwnership.IsUnique
666	                    && previousEntry.EntityState != EntityState.Added
667	                    && previousEntry.EntityState != EntityState.Deleted)
668	                {
669	                    var ordinalProperty = previousEntry.EntityType.FindPrimaryKey()!.Properties.Last();
670	                    ordinal = (int)previousEntry.GetCurrentProviderValue(ordinalProperty)! - 1;
671	                }
672	
673	                var pathEntry = new JsonPartialUpdatePathEntry(
674	                    currentOwnership.PrincipalEntityType.IsMappedToJson() ? jsonPropertyName : "$",
675	                    ordinal,
676	                    currentEntry,
677	                    currentOwnership.GetNavigation(pointsToPrincipal: false)!, // TODO: Handle complex properties, Issue #36429
678	                    ElementEntry: ordinal == null ? null : previousEntry);
679	
680	                result.Insert(0, pathEntry);
681	            }
682	
683	            var modifiedMembers = entry.EntityType.GetFlattenedProperties().Where(entry.IsModified).ToList();
684	            if (modifiedMembers.Count == 1)
685	            {
686	                result.Add(
687	                    new JsonPartialUpdatePathEntry(
688	                        modifiedMembers[0].GetJsonPropertyName()!,
689	                        null,
690	                        entry,
691	                        modifiedMembers[0]));
692	            }
693	            else
694	            {
695	                // only add to processed entries list if we are planning to update the entire entity
696	                // (rather than just a single property on that entity)
697	                processedEntries.Add(entry);
698	            }
699	
700	            // parent entity got deleted, no need to do any json-specific processing
701	            return currentEntry?.EntityState == EntityState.Deleted ? null : result;
702	        }
703	
704	        static List<JsonPartialUpdatePathEntry> FindCommonJsonPartialUpdateInfo(
705	            List<JsonPartialUpdatePathEntry> first,
706	            List<JsonPartialUpdatePathEntry> second)
707	        {
708	            var commonPath = new List<JsonPartialUpdatePathEntry>();
709	            for (var i = 0; i < Math.Min(first.Count, second.Count); i++)
710	            {
711	                if (first[i].PropertyName != second[i].PropertyName)
712	                {
713	                    break;
714	                }
715	
716	                if (first[i].Ordinal == second[i].Ordinal)
717	                {
718	                    commonPath.Add(first[i]);
719	                    continue;
720	                }
721	
722	                var common = new JsonPartialUpdatePathEntry(
723	                    first[i].PropertyName,
724	                    null,
725	                    first[i].ParentEntry,
726	                    Property: first[i].Property);
727	
728	                commonPath.Add(common);
729	
730	                break;
731	            }
732	
733	            Check.DebugAssert(commonPath.Count > 0, "Common denominator should always have at least one node - the root.");
734	
735	            return commonPath;
736	        }
737	
738	        void HandleJson(List<IColumnModification> columnModifications)
739	        {
740	            var jsonColumnsUpdateMap = new Dictionary<IColumn, List<JsonPartialUpdatePathEntry>>();
741	            var processedEntries = new List<IUpdateEntry>();
742	            foreach (var entry in _entries)
743	            {
744	                if (!entry.EntityType.IsMappedToJson())
745	                {
746	                    continue;
747	                }
748	
749	                var jsonColumn = GetTableMapping(entry.EntityType)!.Table.FindColumn(entry.EntityType.GetContainerColumnName()!)!;
750	                var jsonPartialUpdateInfo = FindJsonPartialUpdateInfo(entry, processedEntries);
751	                if (jsonPartialUpdateInfo == null)
752	                {
753	                    continue;
754	                }
755	
756	                if (jsonColumnsUpdateMap.TryGetValue(jsonColumn, out var currentJsonPartialUpdateInfo))
757	                {
758	                    jsonPartialUpdateInfo = FindCommonJsonPartialUpdateInfo(
759	                        currentJsonPartialUpdateInfo,
760	                        jsonPartialUpdateInfo);
761	                }
762	
763	                jsonColumnsUpdateMap[jsonColumn] = jsonPartialUpdateInfo;
764	            }
765	
